let index;
export function searchReadings(ch) {
  if (!index) {
    index = new Map();
    for (const row of RAW.split("\n")) {
      const [syllable, chars] = row.split(":");
      for (const char of chars) {
        if (!index.has(char)) index.set(char, []);
        index.get(char).push(syllable);
      }
    }
  }
  return index.get(ch) || [];
}
